import { EChart, type EChartSetup } from "@/components/ui/echart"
import type { EChartsOption } from "echarts"

const ROOT_PATH = "https://cdn.jsdelivr.net/gh/apache/echarts-examples@88ca004030e999073a15303e5fe32462b8fefae2/public"

// Adapted from the Apache ECharts example "Wish List and Mountain Height" (Apache-2.0):
// https://echarts.apache.org/examples/en/editor.html?c=pictorialBar-hill
const setup: EChartSetup = () => {
  let option!: EChartsOption
  var paperDataURI =
    'data:image/png;base64,';

  option = {
    backgroundColor: '#0f375f',
    tooltip: {},
    legend: {
      textStyle: { color: '#ddd' }
    },
    xAxis: [
      {
        data: ['Christmas Wish List', '', 'Qomolangma', 'Kilimanjaro'],
        axisTick: { show: false },
        axisLine: { show: false },
        axisLabel: {
          margin: 20,
          color: '#ddd',
          fontSize: 14
        }
      }
    ],
    yAxis: {
      splitLine: { show: false },
      axisTick: { show: false },
      axisLine: { show: false },
      axisLabel: { show: false }
    },
    markLine: {
      z: -1
    },
    animationEasing: 'elasticOut',
    series: [
      {
        type: 'pictorialBar',
        name: 'All',
        emphasis: {
          scale: true
        },
        label: {
          show: true,
          position: 'top',
          formatter: '{c} m',
          fontSize: 16,
          color: '#e54035'
        },
        data: [
          {
            value: 13000,
            symbol: 'image://' + paperDataURI,
            symbolRepeat: true,
            symbolSize: ['130%', '20%'],
            symbolOffset: [0, 10],
            symbolMargin: '-30%',
            animationDelay: function (dataIndex, params: any) {
              return params.index * 30;
            }
          },
          {
            value: '-',
            symbol: 'none'
          },
          {
            value: 8844,
            symbol:
              'image://' + ROOT_PATH + '/data/asset/img/hill-Qomolangma.png',
            symbolSize: ['200%', '105%'],
            symbolPosition: 'end',
            z: 10
          },
          {
            value: 5895,
            symbol:
              'image://' + ROOT_PATH + '/data/asset/img/hill-Kilimanjaro.png',
            symbolSize: ['200%', '105%'],
            symbolPosition: 'end'
          }
        ],
        markLine: {
          symbol: ['none', 'none'],
          label: {
            show: false
          },
          lineStyle: {
            color: '#e54035',
            width: 2
          },
          data: [
            {
              yAxis: 8844
            }
          ]
        }
      },
      {
        name: 'All',
        type: 'pictorialBar',
        barGap: '-100%',
        symbol: 'circle',
        itemStyle: {
          color: '#185491'
        },
        silent: true,
        symbolOffset: [0, '50%'],
        z: -10,
        data: [
          {
            value: 1,
            symbolSize: ['150%', 50]
          },
          {
            value: '-'
          },
          {
            value: 1,
            symbolSize: ['200%', 50]
          },
          {
            value: 1,
            symbolSize: ['200%', 50]
          }
        ]
      }
    ]
  };
  return option
}

export function EchartsPictorialBarHill() {
  return <EChart setup={setup} />
}
